// Generated by pnpm new. A per-sketch copy: edit freely for this sketch only (docs/spec/publish-pipeline.md).
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { defineConfig, type Plugin } from 'vite';

// Dev only. The debug pane POSTs the current knob values here and this writes params.json, which is the
// single source of truth for the sketch -- no value is hardcoded in the .ts (see params.ts).
//
// apply: 'serve' keeps the endpoint out of the build entirely, and writing the file is itself a source
// change, so Vite reloads the page afterwards: what the reload shows was read back from disk, not from
// memory. Reloading *without* saving therefore drops the edits, which is the intended behaviour.
const saveParams: Plugin = {
  name: 'save-params',
  apply: 'serve',
  configureServer(server) {
    server.middlewares.use('/__params', (req, res, next) => {
      if (req.method !== 'POST') return next();
      let body = '';
      req.on('data', (chunk) => (body += chunk));
      req.on('end', () => {
        try {
          const values: unknown = JSON.parse(body);
          // Guard against writing something the sketch cannot load: params.ts throws on a non-numeric key,
          // and a bad write here would leave the sketch broken until the file is fixed by hand.
          const ok =
            typeof values === 'object' &&
            values !== null &&
            !Array.isArray(values) &&
            // Colours are the one non-number: params.ts writes them as "#rrggbb" so the file stays
            // readable, and parses them back to 0xRRGGBB on load.
            Object.values(values).every(
              (v) => (typeof v === 'number' && Number.isFinite(v)) || (typeof v === 'string' && /^#[0-9a-f]{6}$/i.test(v)),
            );
          if (!ok) throw new Error('expected a flat object of finite numbers and #rrggbb colours');
          writeFileSync(join(import.meta.dirname, 'params.json'), JSON.stringify(values, null, 2) + '\n');
          res.end('ok');
        } catch (error) {
          res.statusCode = 400;
          res.end(String(error));
        }
      });
    });
  },
};

// Property mangling renames every unquoted property (same policy as PaleGL for function-based code).
// Properties referenced by string (Tweakpane bindings, uniform names, JSON keys) must be quoted in the object
// literal: { 'speed': 1 }. Breakage only shows in the build output, so check the build output (docs/coding.md).
//
// OFF for this sketch, and the reason is not this sketch's own code: three's built-in materials resolve
// `#include <common>` by pulling the chunk name out of the shader *string* and looking it up on ShaderChunk.
// Mangling renames ShaderChunk's keys, the lookup returns undefined, and the build dies on `.replace` of
// undefined before the first frame. Any sketch using three's own materials (MeshStandardMaterial, the
// PMREM generator, ...) has to turn this off; 001 survived it only because it was RawShaderMaterial with
// hand-written GLSL and no #include.
const mangleProperties = false;

export default defineConfig({
  root: import.meta.dirname,
  plugins: [saveParams],
  // Emit imported JSON as JSON.parse('...') rather than an object literal. An object literal's keys are
  // fair game for terser's property mangling (`keep_quoted` only spares keys that are quoted *in the
  // source*, and the bundler re-emits them unquoted), which would silently rename every knob in the build.
  json: { stringify: true },
  // .hdr is not one of Vite's known asset types, so without this `import url from './env.hdr?url'`
  // resolves in dev and then emits nothing into the build -- the sketch loses its reflections only in
  // the published output, which is the hardest kind of breakage to notice (docs/decisions/0008).
  assetsInclude: ['**/*.hdr'],
  // Relative base so the build output can be moved (decision 0004). Do not write absolute paths in sketch code.
  base: './',
  build: {
    // Output straight into public/lab/<slug>/ (committed; served by Pages as-is. decision 0001).
    outDir: '../../public/lab/greeble-flow',
    emptyOutDir: true,
    target: 'esnext',
    // Sketches are a single chunk; the modulepreload polyfill is dead weight.
    modulePreload: { polyfill: false },
    minify: 'terser',
    terserOptions: {
      mangle: {
        toplevel: true,
        ...(mangleProperties ? { properties: { keep_quoted: true } } : {}),
      },
      compress: {
        passes: 1,
        arguments: true,
        // booleans_as_integers is OFF, and like mangleProperties above the reason is three's code, not
        // this sketch's. It rewrites true/false as 1/0, and three's HDRLoader parses the Radiance header
        // with a reader whose end-of-line signal is a boolean compared by identity -- as integers the
        // comparison stops matching and the loader dies on "Bad File Format: missing image size
        // specifier". It renders perfectly in dev and throws in the build, which is the same shape of
        // failure as the ShaderChunk one and the same reason `artifacts run` exists (decision 0008).
        // Found by bisecting the compress options; it was worth a few bytes.
        booleans_as_integers: false,
        drop_console: true,
        drop_debugger: true,
        keep_fargs: false,
        module: true,
        pure_getters: true,
        unsafe: true,
        unsafe_math: true,
        unsafe_methods: true,
        unsafe_proto: true,
        unsafe_undefined: true,
      },
    },
  },
});
